      let reference;
      if (/^[|>&*!{\[]/.test(scalar) || !scalar) {
        finding('warnings', 'DYNAMIC_PROMPT_REFERENCE', manifest, index + 1, 'Non-literal prompt reference requires runtime manifest validation.');
