            if (judgment) {
                const jEval = await JudgmentEngine.evaluate(judgment, evalContext);
                judgmentResult = jEval;
                fallbackTriggered = Boolean(jEval.fallbackTriggered);
                fallbackTarget = jEval.fallbackTarget;
                if (!jEval.passed) {
                    return {
                        passed: false,
                        error: jEval.error || `Judgment rejected: '${judgment.criterion}' (confidence: ${jEval.confidence})`,
                        judgmentResult,
                        fallbackTriggered,
                        fallbackTarget,
                    };
                }
            }
            // 1. Evaluate custom guard function file if specified (SEC-01)
            if (guardFunctionPath && evalContext.skillDir) {
                const ext = path.extname(guardFunctionPath).toLowerCase();
                if (!ALLOWED_GUARD_EXTENSIONS.includes(ext)) {
                    return {
                        passed: false,
                        error: `Guard function must be a JavaScript file (.js, .mjs, .cjs): ${guardFunctionPath}`,
                    };
                }
                const skillRoot = path.resolve(evalContext.skillDir);
                const fullPath = path.resolve(skillRoot, guardFunctionPath);
                const relativePath = path.relative(skillRoot, fullPath);
                if (relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
                    return {
                        passed: false,
                        error: `Guard function path escapes skill directory: ${guardFunctionPath}`,
                    };
                }
                if (fs.existsSync(fullPath)) {
                    const realSkillRoot = fs.existsSync(skillRoot) ? fs.realpathSync(skillRoot) : skillRoot;
                    const realFullPath = fs.realpathSync(fullPath);
                    const realRel = path.relative(realSkillRoot, realFullPath);
                    if (realRel.startsWith('..') || path.isAbsolute(realRel)) {
                        return {
                            passed: false,
                            error: `Guard function path escapes skill directory: ${guardFunctionPath}`,
                        };
                    }
                    const fileUrl = pathToFileURL(realFullPath).href;
                    const module = await import(fileUrl);
                    const fn = module.default || module.guard || module.check;
                    if (typeof fn === 'function') {
                        const result = await fn(evalContext);
                        return {
                            passed: Boolean(result),
                            judgmentResult,
                            fallbackTriggered,
                            fallbackTarget,
                        };
                    }
                    return {
                        passed: false,
                        error: `Guard function file does not export a valid function (default, guard, check): ${guardFunctionPath}`,
                        judgmentResult,
                        fallbackTriggered,
                        fallbackTarget,
                    };
                }
                else {
                    return {
                        passed: false,
                        error: `Guard function file not found: ${guardFunctionPath}`,
                        judgmentResult,
                        fallbackTriggered,
                        fallbackTarget,
                    };
                }
            }
            // 2. Evaluate inline expression using hardened node:vm sandbox
            if (guardExpr) {
                // Deep clone / sanitize sandbox variables to prevent prototype pollution or escape
                const sandbox = {
                    event: JSON.parse(JSON.stringify(evalContext.event)),
                    context: JSON.parse(JSON.stringify(evalContext.context || {})),
                    currentState: String(evalContext.currentState),
                    state: String(evalContext.currentState),
                    payload: JSON.parse(JSON.stringify(evalContext.event.payload || {})),
                    Boolean,
                    Number,
                    String,
                    Array,
                    Object,
                    Math,
                    JSON,
                };
                const vmContext = vm.createContext(sandbox, {
                    codeGeneration: {
                        strings: false, // Disable eval / new Function inside guard
                        wasm: false,
                    },
                });
                // Wrap expression safely with 100ms timeout
                const script = new vm.Script(`"use strict"; Boolean(${guardExpr})`);
                const result = script.runInContext(vmContext, { timeout: 100 });
                return {
                    passed: Boolean(result),
                    judgmentResult,
                    fallbackTriggered,
                    fallbackTarget,
                };
            }
            return {
                passed: true,
                judgmentResult,
                fallbackTriggered,
                fallbackTarget,
            };
        }
        catch (err) {
            return {
                passed: false,
                error: `Guard evaluation failed: ${err.message}`,
            };
        }
    }
}

handleSignal
handleSignal(signalName, payload = {}, metadata = {}) {
        const key = `${this.workspaceDir}\u0000${this.manifest.name}\u0000${this.jobId || 'default'}`;
        const previous = signalSerialByRun.get(key) || Promise.resolve();
        const operation = previous.then(() => this.processSignal(signalName, payload, metadata));
        const settled = operation.then(() => undefined, () => undefined);
        signalSerialByRun.set(key, settled);
        void settled.then(() => {
            if (signalSerialByRun.get(key) === settled)
                signalSerialByRun.delete(key);
        });
        return operation;
    }
transitionBetweenPaths
transitionBetweenPaths(fromPath, toPath, signalName, causationId, payload, metrics) {
        // 1. Find Lowest Common Ancestor (LCA)
        let lcaDepth = 0;
        const maxDepth = Math.min(fromPath.length, toPath.length);
        while (lcaDepth < maxDepth && fromPath[lcaDepth] === toPath[lcaDepth]) {
            lcaDepth++;
        }
        // 2. Exit states from leaf up to LCA (exclusive)
        for (let i = fromPath.length; i > lcaDepth; i--) {
            const exitSubpath = fromPath.slice(0, i);
            this.executeExitHook(exitSubpath, signalName);
        }
        // 3. Record STATE_TRANSITION event in EventStore
        this.eventStore.append('STATE_TRANSITION', {
            from: fromPath.join('.'),
            to: toPath.join('.'),
            signal: signalName,
            payload,
            metrics,
        }, {
            state: toPath.join('.'),
            causationId,
        });
        // 4. Update active state path and context updates
        this.activeStatePath = [...toPath];
        if (payload?.contextUpdates) {
            this.updateContext(payload.contextUpdates);
        }
        // 5. Enter states from LCA (exclusive) down to leaf
        this.enterPath(toPath, fromPath.slice(0, lcaDepth), signalName);
    }
enterPath
enterPath(targetPath, ancestorPath, triggerSignal) {
        for (let i = ancestorPath.length + 1; i <= targetPath.length; i++) {
            const enterSubpath = targetPath.slice(0, i);
            this.executeEntryHook(enterSubpath, triggerSignal);
        }
    }
executeEntryHook
executeEntryHook(statePath, triggerSignal) {
        const def = this.getStateDefinition(statePath);
        if (!def)
            return;
        const stateKey = statePath.join('.');
        // Track state visitation for delta detection on revisits
        const prevVisit = this.stateVisits.get(stateKey);
        const visitSeq = this.eventStore.getLatestSequence();
        const contextSnapshot = { ...this.context };
        if (prevVisit) {
            this.eventStore.append('STATE_REVISITED', {
                state: stateKey,
                previous_visit_seq: prevVisit.seq,
                current_seq: visitSeq,
                changed_keys: this.computeChangedKeys(prevVisit.context_snapshot, this.context),
                context_snapshot: contextSnapshot,
            }, { state: stateKey, causationId: prevVisit.seq.toString() });
        }
        else {
            this.eventStore.append('STATE_VISITED', {
                state: stateKey,
                seq: visitSeq,
                context_snapshot: contextSnapshot,
            }, { state: stateKey });
        }
        this.stateVisits.set(stateKey, {
            state: stateKey,
            seq: visitSeq,
            context_snapshot: contextSnapshot,
        });
        if (def.human_gate) {
            this.eventStore.append('HUMAN_GATE_ENTERED', {
                state: statePath.join('.'),
                gateType: def.human_gate.type,
                tool: def.human_gate.tool || 'ask_question',
                options: def.human_gate.options,
            }, { state: statePath.join('.') });
        }
        if (def.on_enter) {
            for (const action of def.on_enter) {
                if (action.set_context) {
                    this.updateContext(action.set_context);
                }
                if (action.emit_signal) {
                    this.eventStore.append('STATE_ENTRY_HOOK', {
                        state: statePath.join('.'),
                        signalEmitted: action.emit_signal,
                        action: action.action,
                    }, { state: statePath.join('.') });
                    // Queue signal to execute transition cleanly after current cycle
                    this.signalQueue.push({
                        signal: action.emit_signal,
                        payload: {},
                        metadata: { source: `on_enter:${statePath.join('.')}` },
                    });
                }
            }
        }
    }
executeExitHook
executeExitHook(statePath, triggerSignal) {
        const def = this.getStateDefinition(statePath);
        if (!def || !def.on_exit)
            return;
        for (const action of def.on_exit) {
            if (action.set_context) {
                this.updateContext(action.set_context);
            }
            if (action.emit_signal) {
                this.eventStore.append('STATE_EXIT_HOOK', {
                    state: statePath.join('.'),
                    signalEmitted: action.emit_signal,
                    action: action.action,
                }, { state: statePath.join('.') });
                // Queue signal
                this.signalQueue.push({
                    signal: action.emit_signal,
                    payload: {},
                    metadata: { source: `on_exit:${statePath.join('.')}` },
                });
            }
        }
    }
getStateDefinition
getStateDefinition(pathSegments) {
        if (pathSegments.length === 0)
            return null;
        const rootName = pathSegments[0];
        let current = this.manifest.states[rootName];
        if (!current)
            return null;
        for (let i = 1; i < pathSegments.length; i++) {
            const seg = pathSegments[i];
            if (!current.substates || !current.substates[seg]) {
                return null;
            }
            current = current.substates[seg];
        }
        return current;
    }
close
close() {
        this.eventStore.close();
    }

